ValidateDiagFunc.expression:
func(v interface{}, p cty.Path) (diags diag.Diagnostics) {
	value := v.(string)

	if value == "" || value == "inherit" {
		return
	}

	i, err := strconv.Atoi(value)
	if err != nil {
		diags = diag.Errorf(
			"expected dscp value (%s) to be empty string or 'inherit' or integer 0..63", value)
		return
	}

	if i < 0 || i > 63 {
		diags = diag.Errorf(
			"expected %s to be in the range 0 - 63, got %d", value, i)
		return
	}

	return
}

DiffSuppressFunc.expression:
func(k, old, new string, d *schema.ResourceData) bool {
	if old == new {
		return true
	}

	if AlwaysPresentNotUserProvided(k, old, new, d) {
		return true
	}

	if old == "" || new == "" {
		return false
	}

	o := strings.Split(old, ",")
	n := strings.Split(new, ",")
	if len(o) != 2 || len(n) != 2 {
		panic(fmt.Sprintf("[Keepalive] wrong keepalive format, old: '%v', new: '%v'", old, new))
	}

	if o[1] != n[1] {
		return false
	}

	oDuration, err := ParseDuration(o[0], time.Second)
	if err != nil {
		panic("[Keepalive] parse 'old' duration error: " + err.Error())
	}

	nDuration, err := ParseDuration(n[0], time.Second)
	if err != nil {
		panic("[Keepalive] parse 'new' duration error: " + err.Error())
	}

	return oDuration.Seconds() == nDuration.Seconds()
}

