	if diags.HasError() {
		return diags
	}

	if d.Get("launch_trigger").(string) != "" {
		startScript(ctx, resSchema, d, m)
	}

	return ResourceRead(ctx, resSchema, d, m)
}

UpdateContext.expression:
func(ctx context.Context, d *schema.ResourceData, m interface{}) diag.Diagnostics {
	diags := ResourceUpdate(ctx, resSchema, d, m)
	if diags.HasError() {
