PropDscpRw.expression:
&schema.Schema{

	Type:     schema.TypeString,
	Optional: true,
	Default:  "inherit",
	ValidateDiagFunc: func(v interface{}, p cty.Path) (diags diag.Diagnostics) {
		value := v.(string)

		if value == "" || value == "inherit" {
			return
		}

		i, err := strconv.Atoi(value)
		if err != nil {
			diags = diag.Errorf(
				"expected dscp value (%s) to be empty string or 'inherit' or integer 0..63", value)
			return
		}

		if i < 0 || i > 63 {
			diags = diag.Errorf(
				"expected %s to be in the range 0 - 63, got %d", value, i)
			return
		}

		return
	},
	Description: "Set dscp value in GRE header to a fixed value '0..63' or 'inherit' from dscp value taken " +
		"from tunnelled traffic.",
}

ValidateDiagFunc.expression:
func(v interface{}, p cty.Path) (diags diag.Diagnostics) {
	value := v.(string)

	if value == "" || value == "inherit" {
		return
	}

	i, err := strconv.Atoi(value)
	if err != nil {
		diags = diag.Errorf(
			"expected dscp value (%s) to be empty string or 'inherit' or integer 0..63", value)
		return
	}

	if i < 0 || i > 63 {
		diags = diag.Errorf(
			"expected %s to be in the range 0 - 63, got %d", value, i)
		return
	}

	return
}

